// CreatedAtLTE applies the LTE predicate on the "created_at" field.
func CreatedAtLTE(v time.Time) predicate.OpsRequestLog {
	return predicate.OpsRequestLog(sql.FieldLTE(FieldCreatedAt, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OpsRequestLog) predicate.OpsRequestLog {
	return predicate.OpsRequestLog(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.OpsRequestLog) predicate.OpsRequestLog {
	return predicate.OpsRequestLog(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.OpsRequestLog) predicate.OpsRequestLog {
	return predicate.OpsRequestLog(sql.NotPredicates(p))
}
